Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "config": {
    "background": "transparent",
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "labelColor": "#9AA6B0",
      "labelFont": "Segoe UI",
      "labelFontSize": 10,
      "titleColor": "#9AA6B0",
      "titleFont": "Segoe UI",
      "titleFontWeight": "normal",
      "titleFontSize": 10,
      "domain": false,
      "ticks": false,
      "gridColor": "#2C363E"
    },
    "legend": {
      "labelColor": "#9AA6B0",
      "titleColor": "#9AA6B0",
      "labelFont": "Segoe UI"
    },
    "title": {
      "color": "#C9D3DB",
      "font": "Segoe UI Semibold",
      "fontSize": 12,
      "fontWeight": "normal",
      "anchor": "start",
      "offset": 12
    },
    "locale": {
      "number": {
        "decimal": ",",
        "thousands": ".",
        "grouping": [
          3
        ],
        "currency": [
          "R$ ",
          ""
        ]
      },
      "time": {
        "dateTime": "%A, %e de %B de %Y. %X",
        "date": "%d/%m/%Y",
        "time": "%H:%M:%S",
        "periods": [
          "AM",
          "PM"
        ],
        "days": [
          "Domingo",
          "Segunda",
          "Terça",
          "Quarta",
          "Quinta",
          "Sexta",
          "Sábado"
        ],
        "shortDays": [
          "Dom",
          "Seg",
          "Ter",
          "Qua",
          "Qui",
          "Sex",
          "Sáb"
        ],
        "months": [
          "Janeiro",
          "Fevereiro",
          "Março",
          "Abril",
          "Maio",
          "Junho",
          "Julho",
          "Agosto",
          "Setembro",
          "Outubro",
          "Novembro",
          "Dezembro"
        ],
        "shortMonths": [
          "Jan",
          "Fev",
          "Mar",
          "Abr",
          "Mai",
          "Jun",
          "Jul",
          "Ago",
          "Set",
          "Out",
          "Nov",
          "Dez"
        ]
      }
    }
  },
  "title": {
    "text": "Potencial × vendido por praça · ordenado pelo potencial, onde está a oportunidade"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "calculate": "datum[''Municipio''] + '' · '' + datum[''UF'']",
      "as": "praca"
    },
    {
      "calculate": "isValid(datum[''ShareAA'']) ? format((datum[''Share''] - datum[''ShareAA'']) * 100, ''+.1f'') + '' p.p.'' : ''''",
      "as": "dpp"
    },
    {
      "calculate": "format(datum[''Share''], ''.1%'') + ''  '' + datum.dpp",
      "as": "lbl"
    },
    {
      "calculate": "format(datum[''Prospects''], '',.0f'') + '' prospects''",
      "as": "prs"
    }
  ],
  "encoding": {
    "y": {
      "field": "praca",
      "type": "nominal",
      "sort": {
        "field": "Potencial",
        "op": "max",
        "order": "descending"
      },
      "axis": {
        "title": null,
        "labelColor": "#F2F4F5",
        "labelFontSize": 12,
        "labelPadding": 12,
        "labelLimit": 220
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "color": "#2F3A44",
        "height": {
          "band": 0.6
        },
        "cornerRadiusEnd": 3
      },
      "encoding": {
        "x": {
          "field": "Potencial",
          "type": "quantitative",
          "axis": {
            "format": "~s",
            "title": null,
            "grid": true,
            "gridDash": [
              2,
              3
            ],
            "tickCount": 5
          }
        },
        "tooltip": [
          {
            "field": "praca",
            "title": "Praça"
          },
          {
            "field": "Potencial",
            "format": ",.0f",
            "title": "Potencial no período"
          },
          {
            "field": "Vendido",
            "format": ",.0f",
            "title": "Vendido"
          },
          {
            "field": "Share",
            "format": ".1%"
          },
          {
            "field": "ShareAA",
            "format": ".1%",
            "title": "Share AA"
          },
          {
            "field": "Prospects",
            "format": ",.0f",
            "title": "Prospects contatáveis"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "bar",
        "color": "#FF8C00",
        "height": {
          "band": 0.26
        },
        "cornerRadiusEnd": 2
      },
      "encoding": {
        "x": {
          "field": "Vendido",
          "type": "quantitative"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 8,
        "fontSize": 12,
        "fontWeight": 600,
        "color": "#F2F4F5"
      },
      "encoding": {
        "x": {
          "field": "Vendido",
          "type": "quantitative"
        },
        "text": {
          "field": "lbl"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 8,
        "dy": 15,
        "fontSize": 10,
        "color": "#9AA6B0"
      },
      "encoding": {
        "x": {
          "field": "Vendido",
          "type": "quantitative"
        },
        "text": {
          "field": "prs"
        }
      }
    }
  ]
}'
